import{_ as e,o,c as r,a3 as d}from"./chunks/framework.BTQ4eCVb.js";const h=JSON.parse('{"title":"Party-first billing — production readiness","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Party-first billing — production readiness | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/deployment/party-billing-production-readiness"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Party-first billing — production readiness | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/deployment/party-billing-production-readiness"}]]},"headers":[],"relativePath":"deployment/party-billing-production-readiness.md","filePath":"deployment/party-billing-production-readiness.md","lastUpdated":1789262965000}'),n={name:"deployment/party-billing-production-readiness.md"};function s(a,t,i,l,c,g){return o(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="party-first-billing-—-production-readiness" tabindex="-1">Party-first billing — production readiness <a class="header-anchor" href="#party-first-billing-—-production-readiness" aria-label="Permalink to &quot;Party-first billing — production readiness&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td><strong>Date</strong></td><td>2026-09-13</td></tr><tr><td><strong>Status</strong></td><td><strong>Go</strong> — audit High/Medium/Low engineering items closed; Ops migrate + staging smoke before production traffic</td></tr><tr><td><strong>Scope</strong></td><td>Contact/company billing hubs + statements (+ PDF); vendor purchasing hubs + statements; list deep links; aged receivables customer identity; catalog <strong>contacts 1.4.0 → 1.5.0</strong>, <strong>companies 1.1.0 → 1.2.0</strong>, <strong>vendors 1.1.0 → 1.2.0</strong></td></tr><tr><td><strong>Companion</strong></td><td><a href="/user-guide/contacts">Contacts user guide</a> · <a href="/user-guide/companies">Companies</a> · <a href="/user-guide/vendors">Vendors</a> · <a href="/user-guide/financial-reports">Financial reports</a> · <a href="/api/tenant-v1-contacts">Contacts API</a> · <a href="/changelog/">CHANGELOG</a></td></tr></tbody></table><hr><h2 id="executive-summary" tabindex="-1">Executive summary <a class="header-anchor" href="#executive-summary" aria-label="Permalink to &quot;Executive summary&quot;">​</a></h2><p>Party records become the hub for AR/AP discovery instead of forcing users through Billing/Purchasing lists only:</p><ul><li>List deep links: <code>/invoices?contact=</code>, <code>?company=</code>, <code>/payments?…</code>, quotations, credit notes, <code>/purchase-orders?vendor=</code>, <code>/expenses?vendor=</code></li><li>Contact/company <strong>Billing</strong> strip (invoiced / paid / balance) + recent docs (incl. credit notes) + <strong>Statement</strong> (JSON + PDF) with opening/closing balance</li><li>Vendor <strong>Purchasing activity</strong> strip (PO/expense spend — not AP payable) + statement (in-app; PDF deferred)</li><li>Aged receivables rows include contact/company identity with SPA drill-downs</li><li>Platform freeze respected — extends existing Contact/Company/Vendor + list pages</li></ul><p><strong>Go / No-Go:</strong> <strong>Go</strong> for staging → production after CI on companion PRs and Ops pre-flight below.</p><table tabindex="0"><thead><tr><th>Gate</th><th>Result</th></tr></thead><tbody><tr><td>Party summary + statement APIs (authz, module entitlement, tenant isolation)</td><td><strong>Pass</strong></td></tr><tr><td>Customer invoice summary excludes draft/cancelled</td><td><strong>Pass</strong></td></tr><tr><td>Customer statement credits = <strong>applied only</strong> (aligns aged AR; excludes issued/refunded)</td><td><strong>Pass</strong></td></tr><tr><td>Vendor summary/statement exclude <strong>draft</strong> + cancelled</td><td><strong>Pass</strong></td></tr><tr><td>Statement <code>opening_balance</code> + closing <code>balance_due</code> (customer + vendor)</td><td><strong>Pass</strong></td></tr><tr><td>SPA hubs + ErrorState on summary failure + statement routes + deep-link chips</td><td><strong>Pass</strong></td></tr><tr><td>Statement button gated by related <code>*.view</code> (not module-only)</td><td><strong>Pass</strong></td></tr><tr><td>Catalog bump migration + CatalogSeeder <strong>1.5.0 / 1.2.0 / 1.2.0</strong></td><td><strong>Pass</strong></td></tr><tr><td>Pest <code>PartyBilling</code> suite (+ aged AR shape + opening balance)</td><td><strong>Pass</strong></td></tr><tr><td>Playwright <code>contacts.party-billing</code> (contact + company + PDF smoke)</td><td><strong>Pass</strong> (verify in CI / headed)</td></tr><tr><td>Docs user/developer/API/CHANGELOG</td><td><strong>Pass</strong></td></tr><tr><td>AP bills / vendor payment module / vendor PDF / mobile statement UI</td><td><strong>N/A</strong> (explicitly deferred)</td></tr></tbody></table><hr><h2 id="audit-findings-closed" tabindex="-1">Audit findings (closed) <a class="header-anchor" href="#audit-findings-closed" aria-label="Permalink to &quot;Audit findings (closed)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Severity</th><th>Finding</th><th>Resolution</th></tr></thead><tbody><tr><td>High</td><td>Vendor drafts inflated purchasing totals</td><td>Exclude draft + cancelled on summary and statement</td></tr><tr><td>High</td><td>Refunded/issued credits reduced statement balance</td><td>Statement credits use <strong>applied</strong> status only</td></tr><tr><td>Medium</td><td>Statement button module-only vs hub <code>*.view</code></td><td>Header Statement requires invoices/payments (or PO/expense) <strong>view</strong></td></tr><tr><td>Medium</td><td>Thin company/vendor e2e</td><td>Company hub + PDF smoke added to <code>contacts.party-billing.spec.ts</code></td></tr><tr><td>Medium</td><td>Hub silent failure on summary error</td><td><code>ErrorState</code> + retry on customer/vendor hub panels</td></tr><tr><td>Low</td><td>No opening-balance on statement</td><td>API + SPA + PDF expose <code>opening_balance</code>; closing labeled clearly</td></tr><tr><td>Low</td><td>Vendor “balance” is spend, not AP payable</td><td>UI/docs: “Purchasing activity” / “Activity total”; API notes clarify</td></tr><tr><td>Low</td><td>Credit notes missing from hub</td><td>Recent credit notes list on customer party hub when module entitled</td></tr></tbody></table><hr><h2 id="catalog-version-path" tabindex="-1">Catalog version path <a class="header-anchor" href="#catalog-version-path" aria-label="Permalink to &quot;Catalog version path&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Migration</th><th>Effect</th></tr></thead><tbody><tr><td><code>2026_09_12_165056_bump_contacts_companies_vendors_for_party_billing</code></td><td>contacts <strong>1.5.0</strong>, companies <strong>1.2.0</strong>, vendors <strong>1.2.0</strong></td></tr></tbody></table><p>Production: <strong>migrate only</strong>. Do <strong>not</strong> <code>db:seed</code> on upgrade. Fresh local/CI seed uses <code>CatalogSeeder</code> versions aligned with these bumps.</p><hr><h2 id="deploy-order" tabindex="-1">Deploy order <a class="header-anchor" href="#deploy-order" aria-label="Permalink to &quot;Deploy order&quot;">​</a></h2><ol><li><strong>Backend</strong> — <code>php artisan migrate --force</code> (catalog bumps)</li><li>Confirm central catalog versions: contacts <strong>1.5.0</strong>, companies <strong>1.2.0</strong>, vendors <strong>1.2.0</strong></li><li>Deploy <strong>SPA</strong> (hubs, deep links, statement pages)</li><li>Deploy <strong>Docs</strong></li><li>Optional: <strong>Mobile</strong> aged receivables type fields (display polish only)</li><li>Staging smoke below</li></ol><p>Suggested merge order: <strong>Backend → Frontend → Docs</strong> (+ Mobile if shipping).</p><p>No new env vars, queues, or scheduler entries.</p><hr><h2 id="pre-flight-checklist" tabindex="-1">Pre-flight checklist <a class="header-anchor" href="#pre-flight-checklist" aria-label="Permalink to &quot;Pre-flight checklist&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Check</th><th>Owner</th><th>Pass?</th></tr></thead><tbody><tr><td>1</td><td>Migrations applied; catalog contacts/companies/vendors versions match table above</td><td>Ops</td><td>☐</td></tr><tr><td>2</td><td>Contact with invoices: Billing strip shows totals; <strong>View invoices</strong> opens <code>?contact=</code> chip</td><td>QA</td><td>☐</td></tr><tr><td>3</td><td>Contact <strong>Statement</strong> date range + opening/closing + PDF download</td><td>QA</td><td>☐</td></tr><tr><td>4</td><td>Company hub + statement PDF</td><td>QA</td><td>☐</td></tr><tr><td>5</td><td>Vendor hub PO/expense totals exclude drafts; statement shows activity labels</td><td>QA</td><td>☐</td></tr><tr><td>6</td><td>Aged receivables shows customer column + links</td><td>QA</td><td>☐</td></tr><tr><td>7</td><td>User without invoices/payments view does not see Statement / Billing on contact</td><td>QA</td><td>☐</td></tr><tr><td>8</td><td>Pest <code>tests/Feature/Tenant/PartyBilling</code> green in CI</td><td>Eng</td><td>☐</td></tr><tr><td>9</td><td>Playwright <code>e2e/tests/contacts/contacts.party-billing.spec.ts</code> green</td><td>QA</td><td>☐</td></tr></tbody></table><hr><h2 id="residual-risks-follow-ups" tabindex="-1">Residual risks / follow-ups <a class="header-anchor" href="#residual-risks-follow-ups" aria-label="Permalink to &quot;Residual risks / follow-ups&quot;">​</a></h2><ol><li>Vendor AP bills / payments module and vendor statement PDF (product backlog).</li><li>EloSync-Mobile party statement UI (web-first this cycle).</li><li>Optional headed vendor hub Playwright (PO/expense path) — not blocking; covered by Pest.</li></ol><hr><h2 id="verdict" tabindex="-1">Verdict <a class="header-anchor" href="#verdict" aria-label="Permalink to &quot;Verdict&quot;">​</a></h2><p><strong>Go</strong> — audit findings closed for this cycle; ship after migrate + staging smoke and green CI on companion PRs.</p>',29)])])}const u=e(n,[["render",s]]);export{h as __pageData,u as default};
